102:   /* ============================================================ OFFICE */
103:   _buildOffice() {
104:     const s = this.scene;
105:     this.office = new THREE.Group();
106:     s.add(this.office);
107: 
108:     // materials
109:     const wall = new THREE.MeshStandardMaterial({ map: wallTexture(), roughness: .93 });
110:     const wains = new THREE.MeshStandardMaterial({ map: wainscotTexture(), roughness: .85 });
111:     const ceil = new THREE.MeshStandardMaterial({ map: ceilingTexture(), roughness: 1 });
112:     const floorM = new THREE.MeshStandardMaterial({ map: floorTexture(), roughness: .42, metalness: .14 });
113:     const trim = mat({ color: 0x2a2118, roughness: .7 });
114:     const metal = new THREE.MeshStandardMaterial({ map: metalTexture(), roughness: .55, metalness: .55 });
115: 
116:     // floor + ceiling
117:     const floor = plane(OFFICE.w * 2 + .4, OFFICE.back - OFFICE.front + .4, floorM, 0, 0, (OFFICE.back + OFFICE.front) / 2, -Math.PI / 2);
118:     floor.receiveShadow = true;
119:     this.office.add(floor);
120:     const ceiling = plane(OFFICE.w * 2 + .4, OFFICE.back - OFFICE.front + .4, ceil, 0, OFFICE.h, (OFFICE.back + OFFICE.front) / 2, Math.PI / 2);
121:     this.office.add(ceiling);
122: 
123:     // helper for wall section with upper paper + lower wainscot
124:     const buildWall = (w, wallH = OFFICE.h) => {
125:       const g = new THREE.Group();
126:       const lower = box(w, .92, .08, wains, 0, .46, 0);
127:       lower.receiveShadow = true;
128:       g.add(lower);
129:       const upperH = wallH - .92;
130:       const upper = plane(w, upperH, wall, 0, .92 + upperH / 2, .041);
131:       g.add(upper);
132:       const rail = box(w, .07, .13, trim, 0, .94, .04);
133:       g.add(rail);
134:       const base = box(w, .14, .1, trim, 0, .07, .04);
135:       g.add(base);
136:       return g;
137:     };
138: 
139:     // front wall (behind desk) at z = front
140:     const fw = buildWall(OFFICE.w * 2);
141:     fw.position.set(0, 0, OFFICE.front);
142:     this.office.add(fw);
143: 
144:     // back wall (behind player)
145:     const bw = buildWall(OFFICE.w * 2);
146:     bw.position.set(0, 0, OFFICE.back);
147:     bw.rotation.y = Math.PI;
148:     this.office.add(bw);
149: 
150:     // side walls with door openings
151:     const zA = OFFICE.front, zB = OFFICE.doorZ - OFFICE.doorW / 2;
152:     const zC = OFFICE.doorZ + OFFICE.doorW / 2, zD = OFFICE.back;
153:     const upperH = OFFICE.h - .92;
154:     for (const side of [-1, 1]) {
155:       const x = side * OFFICE.w;
156:       const ry = side < 0 ? Math.PI / 2 : -Math.PI / 2;
157:       const segs = [[zA, zB], [zC, zD]];
158:       for (const [za, zb] of segs) {
159:         const len = Math.abs(zb - za), cz = (za + zb) / 2;
160:         const lower = plane(len, .92, wains, x, .46, cz, 0, ry);
161:         lower.receiveShadow = true;
162:         const upper = plane(len, upperH, wall, x, .92 + upperH / 2, cz, 0, ry);
163:         upper.receiveShadow = true;
164:         this.office.add(lower, upper);
165:         this.office.add(box(.1, .07, len, trim, x, .945, cz));
166:         this.office.add(box(.1, .15, len, trim, x, .075, cz));
167:       }
168:       // header above the doorway
169:       const headerH = OFFICE.h - OFFICE.doorH;
170:       this.office.add(plane(OFFICE.doorW, headerH, wall, x, OFFICE.doorH + headerH / 2, OFFICE.doorZ, 0, ry));
171:       this.office.add(box(.1, .1, OFFICE.doorW + .2, trim, x, OFFICE.doorH + headerH - .05, OFFICE.doorZ));
172:     }
173: 
174:     // door frames + shutters + hall
175:     for (const side of [-1, 1]) {
176:       const key = side < 0 ? 'left' : 'right';
177:       // frame
178:       const frameM = mat({ color: 0x3a3126, roughness: .5, metalness: .5 });
179:       const frame = new THREE.Group();
180:       frame.add(box(.13, OFFICE.doorH + .08, .12, frameM, 0, OFFICE.doorH / 2, -OFFICE.doorW / 2 - .05));
181:       frame.add(box(.13, OFFICE.doorH + .08, .12, frameM, 0, OFFICE.doorH / 2, OFFICE.doorW / 2 + .05));
182:       frame.add(box(.13, .14, OFFICE.doorW + .22, frameM, 0, OFFICE.doorH + .04, 0));
183:       frame.position.set(side * OFFICE.w, 0, OFFICE.doorZ);
184:       frame.rotation.y = side * Math.PI / 2;
185:       this.office.add(frame);
186: 
187:       // shutter — slides in Y
188:       const shutter = box(.1, OFFICE.doorH + .06, OFFICE.doorW + .04, metal, 0, OFFICE.doorH / 2, 0);
189:       shutter.castShadow = true; shutter.receiveShadow = true;
190:       const sg = new THREE.Group();
191:       sg.position.set(side * OFFICE.w, 0, OFFICE.doorZ);
192:       sg.rotation.y = side * Math.PI / 2;
193:       sg.add(shutter);
194:       shutter.position.y = OFFICE.doorH / 2 + 2.4;
195:       this.office.add(sg);
196:       // warning light strip above door
197:       const strip = box(.05, .035, OFFICE.doorW * .8, new THREE.MeshBasicMaterial({ color: 0x52140f, transparent: true, opacity: .9 }), 0, OFFICE.doorH + .13, 0);
198:       sg.add(strip);
199: 
200:       // button panel (visual only)
201:       const panel = new THREE.Group();
202:       const pm = mat({ color: 0x2b2823, roughness: .6, metalness: .3 });
203:       panel.add(box(.05, .54, .3, pm, 0, 0, 0));
204:       const b1 = box(.03, .1, .11, mat({ color: 0xa8352c, emissive: 0x320704, emissiveIntensity: .5, roughness: .4 }), -.03, .11, 0);
205:       const b2 = box(.03, .1, .11, mat({ color: 0xd0a04a, emissive: 0x2a1a02, emissiveIntensity: .4, roughness: .4 }), -.03, -.11, 0);
206:       panel.add(b1, b2);
207:       panel.position.set(side * (OFFICE.w - .17), 1.34, OFFICE.doorZ + .92);
208:       panel.rotation.y = -side * Math.PI / 2;
209:       this.office.add(panel);
210:       this.doors = this.doors || {};
211:       this.doors[key] = { shutter, group: sg, strip, b1, b2 };
212: 
213:       // hall
214:       this._buildHall(side, key, floorM, wall, wains, trim, ceil);
215:     }
216: 
217:     // baseboards/ceiling strip
218:     this.office.add(box(OFFICE.w * 2, .08, .08, trim, 0, OFFICE.h - .04, OFFICE.front + .04));
219:     this.office.add(box(OFFICE.w * 2, .08, .08, trim, 0, OFFICE.h - .04, OFFICE.back - .04));
220: 
221:     this._buildLights();
222:     this._buildDesk();
223:     this._buildFrontWall();
224:     this._buildBackWall();
225:     this._buildDust();
226: 
227:     // ambient artificial light
228:     this.ambient = new THREE.HemisphereLight(0x8f7c5e, 0x17110c, .36);
229:     this.scene.add(this.ambient);
230:   }
