232:   _buildHall(side, key, floorM, wall, wains, trim, ceil) {
233:     const g = new THREE.Group();
234:     const len = 5.4;
235:     const width = 2.35;
236:     const hallX = side * (OFFICE.w + len / 2);
237:     const floor = plane(len, width, floorM, hallX, .001, OFFICE.doorZ, -Math.PI / 2);
238:     floor.receiveShadow = true;
239:     g.add(floor);
240:     g.add(plane(len, width, ceil, hallX, 2.62, OFFICE.doorZ, Math.PI / 2));
241:     // hallway side walls (parallel to x axis)
242:     for (const zs of [-1, 1]) {
243:       const wg = new THREE.Group();
244:       const lower = box(len, .85, .06, wains, 0, .425, 0);
245:       const upper = plane(len, 1.72, wall, 0, .85 + .86, .031);
246:       wg.add(lower, upper);
247:       wg.add(box(len, .06, .1, trim, 0, .86, .03));
248:       wg.position.set(hallX, 0, OFFICE.doorZ + zs * width / 2);
249:       if (zs < 0) wg.rotation.y = 0; else wg.rotation.y = Math.PI;
250:       g.add(wg);
251:     }
252:     // end wall
253:     const eg = new THREE.Group();
254:     eg.add(box(.08, 2.62, width, wall, 0, 1.31, 0));
255:     eg.position.set(side * (OFFICE.w + len), 0, OFFICE.doorZ);
256:     g.add(eg);
257:     // ceiling lamps
258:     const lampMat = new THREE.MeshBasicMaterial({ color: 0x312a1c });
259:     for (const d of [1.3, 3.6]) {
260:       const lamp = box(.7, .04, .16, lampMat, side * (OFFICE.w + d), 2.56, OFFICE.doorZ);
261:       g.add(lamp);
262:     }
263:     // red EXIT sign just outside the office door
264:     const exitSign = plane(.34, .17, new THREE.MeshBasicMaterial({ map: exitTexture(), transparent: true }), side * (OFFICE.w + .06), 2.06, OFFICE.doorZ + 1.02);
265:     exitSign.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
266:     g.add(exitSign);
267:     const exitGlow = new THREE.PointLight(0xff2a18, 1.6, 3.4, 2);
268:     exitGlow.position.set(side * (OFFICE.w + .28), 2.0, OFFICE.doorZ + 1.02);
269:     g.add(exitGlow);
270:     // dim far-end practical light so the hall reads in the dark
271:     const farGlow = new THREE.PointLight(0x8d7a58, 1.1, 5.5, 2);
272:     farGlow.position.set(side * (OFFICE.w + len - .7), 2.35, OFFICE.doorZ);
273:     g.add(farGlow);
274: 
275:     // posters
276:     const posterSpots = [
277:       { kind: 'celebrate', d: 2.0, z: 0.55, s: .8 },
278:       { kind: 'safety', d: 3.6, z: -1.5, s: .7 },
279:       { kind: 'kids', d: 1.1, z: -1.7, s: .55 }
280:     ];
281:     for (const p of posterSpots) {
282:       const pm = new THREE.MeshStandardMaterial({ map: posterTexture(p.kind), roughness: .9 });
283:       const pl = plane(.62 * p.s / .62, .82 * p.s / .62, pm, side * (OFFICE.w + p.d), 1.5, OFFICE.doorZ + p.z * .7);
284:       pl.scale.set(p.s, p.s, 1);
285:       pl.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
286:       // Put against side wall instead
287:       pl.position.z = OFFICE.doorZ + (p.z > 0 ? width / 2 - .05 : -width / 2 + .05);
288:       pl.rotation.y = p.z > 0 ? Math.PI : 0;
289:       g.add(pl);
290:     }
291:     // floor scuffs and a "wet floor" cone
292:     const cone = new THREE.Mesh(
293:       new THREE.ConeGeometry(.18, .38, 14),
294:       mat({ color: 0xb99a32, roughness: .65 })
295:     );
296:     cone.position.set(side * (OFFICE.w + 1.6), .19, OFFICE.doorZ + .45);
297:     g.add(cone);
298:     this.scene.add(g);
299:     this.doors[key].hall = g;
300: 
301:     // door light source
302:     const light = new THREE.SpotLight(0xffb56a, 0, 9, Math.PI / 4.5, .55, 1.5);
303:     light.position.set(side * (OFFICE.w + .35), 2.45, OFFICE.doorZ);
304:     light.target.position.set(side * (OFFICE.w + 3.4), .3, OFFICE.doorZ);
305:     this.scene.add(light, light.target);
306:     light.castShadow = false;
307:     this.doors[key].light = light;
308:     this.doors[key].lightTarget = light.target;
309: 
310:     // fake volumetric cone
311:     const coneGeo = new THREE.ConeGeometry(1.5, 3.4, 18, 1, true);
312:     const coneMat = new THREE.MeshBasicMaterial({
313:       color: 0xffb060, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
314:       side: THREE.DoubleSide, depthWrite: false
315:     });
316:     const vol = new THREE.Mesh(coneGeo, coneMat);
317:     vol.position.set(side * (OFFICE.w + 1.9), 1.8, OFFICE.doorZ);
318:     vol.rotation.z = side * Math.PI / 2;
319:     vol.rotation.x = 0;
320:     // orient cone to point along hall (from ceiling to floor): rotate so tip up
321:     vol.rotation.set(0, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
322:     vol.position.set(side * (OFFICE.w + 1.7), 1.55, OFFICE.doorZ);
323:     g.add(vol);
324:     this.doors[key].volume = vol;
325:     this.doors[key].volumeBase = coneMat;
326:   }
