867:   /* ============================================================ UPDATE */
868:   update(dt, opts = {}) {
869:     this.time += dt;
870:     const t = this.time;
871: 
872:     if (this.office.visible) {
873:       // look smoothing
874:       if (this.lookEnabled) {
875:         this.yaw += (this.targetYaw - this.yaw) * Math.min(1, dt * 12);
876:         this.pitch += (this.targetPitch - this.pitch) * Math.min(1, dt * 12);
877:         const breath = Math.sin(t * 1.4) * .004 + Math.sin(t * .53) * .006;
878:         this.camera.position.set(
879:           this.cameraBase.x + Math.sin(t * .37) * .012 - this.yaw * .006,
880:           this.cameraBase.y + breath,
881:           this.cameraBase.z
882:         );
883:         this.camera.rotation.set(this.pitch + Math.sin(t * .7) * .0015, this.yaw, Math.sin(t * .31) * .002);
884:       } else {
885:         this.camera.rotation.set(this.pitch, this.yaw, 0);
886:       }
887: 
888:       // doors
889:       for (const side of ['left', 'right']) {
890:         const target = this.doorTarget[side];
