607: /* ------------------------------------------------------------------ HUD / feed */
608: function updateHud(force = false) {
609:   if (!game) return;
610:   const pct = Math.round(game.getPowerPct());
611:   const time = game.clockString();
612:   if (force || time !== lastHud.time) { els.hudTime.textContent = time; lastHud.time = time; }
613:   if (force || pct !== lastHud.power) {
614:     els.powerPct.textContent = `${pct}%`;
615:     const on = Math.ceil(pct / 10);
616:     els.powerBars.forEach((b, i) => {
617:       b.className = i < on ? (pct < 12 ? 'crit' : pct < 30 ? 'low' : 'on') : '';
618:     });
619:     lastHud.power = pct;
620:   }
621:   const low = pct <= 18;
622:   if (force || low !== lastHud.low) {
623:     els.power.classList.toggle('critical', low);
624:     document.body.classList.toggle('power-low', low && state === 'playing');
625:     lastHud.low = low;
626:   }
627:   const usage = Math.round(game.usage * 2) / 2;
628:   if (force || usage !== lastHud.usage) {
629:     els.usageBars.forEach((b, i) => {
630:       const v = i + 1;
631:       b.className = usage >= v - .2 ? (usage >= 3 ? 'hot' : 'on') : '';
632:     });
633:     lastHud.usage = usage;
634:   }
635:   const doors = `${game.doors.left ? 1 : 0}${game.doors.right ? 1 : 0}`;
636:   if (force || doors !== lastHud.doors) {
637:     document.querySelector('[data-action="leftDoor"]').classList.toggle('on', game.doors.left);
638:     document.querySelector('[data-action="rightDoor"]').classList.toggle('on', game.doors.right);
639:     lastHud.doors = doors;
640:   }
641:   const lights = `${game.lights.left ? 1 : 0}${game.lights.right ? 1 : 0}`;
642:   if (force || lights !== lastHud.lights) {
643:     const l = document.querySelector('[data-action="leftLight"]');
644:     const r = document.querySelector('[data-action="rightLight"]');
645:     l.classList.toggle('on', game.lights.left);
646:     r.classList.toggle('on', game.lights.right);
647:     l.classList.toggle('light', true);
648:     r.classList.toggle('light', true);
649:     lastHud.lights = lights;
650:   }
651:   if (force || game.camOpen !== lastHud.cam) {
652:     els.camsBtn.classList.toggle('active', game.camOpen);
653:     lastHud.cam = game.camOpen;
654:   }
655:   const lureReady = game.lureReady();
656:   const lureKey = `${lureReady}|${Math.ceil(game.lureCd)}|${game.blackout}`;
657:   if (force || lureKey !== lastHud.lure) {
658:     els.lureBtn.classList.toggle('ready', lureReady);
659:     els.lureBtn.classList.toggle('busy', !lureReady && !game.blackout);
660:     els.lureState.textContent = game.blackout ? 'NO POWER' : lureReady ? 'READY' : `${Math.ceil(game.lureCd)}s`;
661:     els.lureCd.style.width = `${Math.min(100, Math.max(0, (1 - game.lureCd / game.lureCooldown) * 100))}%`;
662:     lastHud.lure = lureKey;
663:   }
664:   updateCamAlerts(force);
665: }
