695: function syncWorldCharacters() {
696:   if (!game.ai) return;
697:   for (const side of ['left', 'right']) {
698:     const a = game.aiAtDoor(side);
699:     const type = a ? (a.name === 'freddy' ? 'freddy' : a.name) : null;
700:     if (cornerCache[side] !== type) {
701:       cornerCache[side] = type;
702:       world.setCornerCharacter(side, type);
703:     }
704:   }
705:   const f = game.foxy;
706:   const running = f.running;
707:   if (world._foxyRunning !== running) {
708:     world._foxyRunning = running;
709:     if (!running) world.setFoxyRunning(false);
710:   }
711:   if (running) world.setFoxyRunning(true, clamp(f.runT / 1.75, 0, 1));
712: }
