714: /* ------------------------------------------------------------------ loop */
715: function tick(now) {
716:   requestAnimationFrame(tick);
717:   let dt = (now - last) / 1000;
718:   last = now;
719:   if (dt > .1) dt = .1;
720:   if (dt <= 0) dt = .016;
721: 
722:   // keyboard look
723:   if (state === 'playing' && !game.camOpen) {
724:     let kx = 0, ky = 0;
725:     if (keys.has('arrowleft') || keys.has('a')) kx -= 1;
726:     if (keys.has('arrowright') || keys.has('d')) kx += 1;
727:     if (keys.has('arrowup') || keys.has('w')) ky -= 1;
728:     if (keys.has('arrowdown') || keys.has('s')) ky += 1;
729:     if (kx || ky) {
730:       look.yaw = clamp(look.yaw - kx * dt * 1.35, -1.52, 1.52);
731:       look.pitch = clamp(look.pitch - ky * dt * .75, -.32, .3);
732:       world.targetYaw = look.yaw;
733:       world.targetPitch = look.pitch;
734:     }
735:   }
736: 
737:   if (state === 'playing') {
738:     game.update(dt);
739:     updateHud();
740:     syncWorldCharacters();
741:     for (const side of ['left', 'right']) {
742:       world.setDoor(side, game.doors[side]);
743:       world.setLight(side, game.lights[side]);
744:     }
745:     world.setPower(game.power / 100);
746:     if (game.camOpen) {
747:       feedAcc += dt;
748:       if (feedAcc > .075) {
749:         feedAcc = 0;
750:         feed.draw(game, .075);
751:         setFeedClock();
752:       }
753:     }
754:   } else if (state === 'dead' || state === 'won') {
755:     world.setPower(game.power / 100);
756:   }
757: 
758:   world.update(dt);
759: 
760:   // adaptive quality for sustained mobile framerates
761:   fpsAcc += dt; fpsFrames++;
762:   if (fpsAcc > 2.2) {
763:     const fps = fpsFrames / fpsAcc;
764:     if (fps < 46 && quality > .62) {
765:       quality = Math.max(.62, quality - .11);
766:       world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
767:       goodWindows = 0;
768:     } else if (fps > 57 && quality < 1) {
769:       goodWindows++;
770:       if (goodWindows >= 3) {
771:         quality = Math.min(1, quality + .08);
772:         world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
773:         goodWindows = 0;
774:       }
775:     }
776:     fpsAcc = 0; fpsFrames = 0;
777:   }
778: }
